//! The agent action admission contract, as execution-core reads it (WS24-S5).
//!
//! The contract is generated by the Frontend from the typed side map and the action
//! registry, and vendored here byte for byte. These tests hold the Model Plane side of
//! what it claims: every closed row names a known reason, every row is closed to ZDR,
//! the one write is pinned to the digest this service's ticket tool sends, every Do
//! executor the contract names exists in these sources, and the seven eligible ids with
//! no owner path have no executor here. A drift fails in this crate, not in production.

use std::path::{Path, PathBuf};

const CONTRACT: &str = include_str!("fixtures/agent-action-admission.json");

const EXEMPT_REASONS: [&str; 7] = [
    "human_identity_or_security",
    "approval_authority",
    "ui_state_only",
    "irreversible_destructive",
    "org_lifecycle_needs_control_review",
    "no_owner_executor",
    "agent_cannot_self_govern",
];

fn rows() -> Vec<serde_json::Value> {
    let contract: serde_json::Value =
        serde_json::from_str(CONTRACT).expect("the admission contract parses");
    assert_eq!(contract["contract"], "agent-action-admission");
    contract["rows"].as_array().expect("rows is an array").clone()
}

/// Every `.rs` file under this crate's `src`, as text. These checks are about how two
/// services line up, not about a value a unit test can observe, so they read the sources.
fn service_source() -> String {
    fn walk(dir: &Path, out: &mut String) {
        for entry in std::fs::read_dir(dir).expect("src is readable") {
            let path: PathBuf = entry.expect("directory entry").path();
            if path.is_dir() {
                walk(&path, out);
            } else if path.extension().is_some_and(|ext| ext == "rs") {
                out.push_str(&std::fs::read_to_string(&path).expect("source is UTF-8"));
            }
        }
    }
    let mut out = String::new();
    walk(&Path::new(env!("CARGO_MANIFEST_DIR")).join("src"), &mut out);
    out
}

#[test]
fn every_row_is_closed_to_zdr_and_every_closed_row_names_a_known_reason() {
    for row in rows() {
        let id = row["actionId"].as_str().expect("actionId");
        assert_eq!(row["zdr_allowed"], false, "{id} must not be offered under ZDR");
        match row["access"].as_str().expect("access") {
            "none" => {
                let reason = row["exemptReason"]
                    .as_str()
                    .unwrap_or_else(|| panic!("{id} is closed without a reason"));
                assert!(
                    EXEMPT_REASONS.contains(&reason),
                    "{id} carries the unknown reason `{reason}`"
                );
            }
            "read" | "write_approval" => {
                assert!(row["exemptReason"].is_null(), "{id} is open and must carry no reason");
            }
            other => panic!("{id} has the unknown access `{other}`"),
        }
    }
}

#[test]
fn tickets_create_is_the_only_write_and_its_digest_is_the_one_this_service_sends() {
    let rows = rows();
    let writes: Vec<&str> = rows
        .iter()
        .filter(|row| row["access"] == "write_approval")
        .filter_map(|row| row["actionId"].as_str())
        .collect();
    assert_eq!(writes, vec!["tickets.create"]);

    let row = rows
        .iter()
        .find(|row| row["actionId"] == "tickets.create")
        .expect("the tickets.create row");
    let digest = row["schemaHash"].as_str().expect("tickets.create carries a digest");
    assert_eq!(
        digest,
        "sha256:c3aa12ec85c2d79f08e5e8cc726fd75af10ddab0b29f2a6e0dddb0bd42bb56df"
    );
    assert!(
        include_str!("../src/ticket_tools.rs").contains(digest),
        "ticket_tools.rs must send the digest the contract pins"
    );
}

#[test]
fn every_do_executor_the_contract_names_is_defined_in_this_service() {
    let source = service_source();
    for row in rows() {
        let id = row["actionId"].as_str().expect("actionId");
        if let Some(tool) = row["executor"]["do"].as_str() {
            assert!(
                source.contains(&format!("\"{tool}\"")),
                "{id} names the Do tool `{tool}`, which execution-core does not define"
            );
        }
    }
}

#[test]
fn every_do_executor_the_contract_names_is_bound_to_a_capability() {
    for row in rows() {
        let id = row["actionId"].as_str().expect("actionId");
        if let Some(tool) = row["executor"]["do"].as_str() {
            assert!(
                execution_core::capability_policy::trusted_capability_id(tool).is_some(),
                "{id} names the Do tool `{tool}`, which no capability binds"
            );
        }
    }
}

#[test]
fn the_owner_read_the_contract_names_is_the_one_this_service_offers() {
    use execution_core::runtime_loop::owner_reads;

    let rows = rows();
    let row = rows
        .iter()
        .find(|row| row["actionId"] == owner_reads::ACTION_ID)
        .expect("the owner read has a contract row");
    assert_eq!(row["access"], "read");
    assert_eq!(row["executor"]["do"], owner_reads::TOOL_NAME);
    assert_eq!(
        execution_core::capability_policy::trusted_capability_id(owner_reads::TOOL_NAME).as_deref(),
        Some("cap.retrieval.query")
    );
    // Offered only under the admission switch, and never to a run that is retention-bound.
    assert!(owner_reads::permitted(true, false));
    assert!(!owner_reads::permitted(false, false));
    assert!(!owner_reads::permitted(true, true));
}

#[test]
fn the_seven_eligible_ids_without_an_owner_path_have_no_executor_here() {
    let source = service_source();
    let unexecutable: Vec<String> = rows()
        .into_iter()
        .filter(|row| row["eligible"] == true && row["access"] == "none")
        .filter_map(|row| row["actionId"].as_str().map(str::to_owned))
        .collect();
    assert_eq!(unexecutable.len(), 7, "the visible debt is exactly seven ids");
    for id in &unexecutable {
        assert!(
            !source.contains(id.as_str()),
            "{id} is eligible without an owner path, yet execution-core names it"
        );
    }
}
